    tests_run = 0
    tests_passed = 0
    failures = []

    def check(inst):
        nonlocal tests_run, tests_passed
        tests_run += 1
        try:
            OneInThreeSat.validate(inst)
        except Exception as e:  # noqa: BLE001
            failures.append((inst, f"source invalid: {e}"))
            return
        expected = solve_one_in_three_sat(inst)
        try:
            out = reduce(inst)
